const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2520, -29.9027]).buffer(5000); // 5km buffer around La Serena
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';

  // 2. Data Acquisition - CHIRPS daily precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(laSerena);

  const collectionSize = chirps.size().getInfo();
  console.log(`July 2022 CHIRPS images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate total monthly precipitation (mm)
  const monthlyPrecip = chirps.sum();

  // 4. Check valid pixels
  const pixelCount = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels in region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate mean precipitation in region
  const meanPrecip = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Total July 2022 rainfall: ${meanPrecip?.toFixed(2)} mm`);

  // 6. Validation & Final Answer
  if (meanPrecip === null || meanPrecip === undefined || isNaN(meanPrecip)) {
    console.log("<answer>C3</answer>");
  } else if (meanPrecip >= 60) { // 60mm = 6cm
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
